function change(amount, coins) {
  const memo = new Map();                        // "i,left" -> combinations
  const ways = (i, left) => {                    // combinations of coins[i..] that make left
    if (left === 0) return 1;
    if (i === coins.length) return 0;
    const key = i + "," + left;
    if (memo.has(key)) return memo.get(key);
    let count = ways(i + 1, left);               // no more of coin i
    if (coins[i] <= left) count += ways(i, left - coins[i]);   // one more coin i: stay on i
    memo.set(key, count);
    return count;
  };
  return ways(0, amount);
}

from functools import cache

def change(amount, coins):
    @cache
    def ways(i, left):                    # combinations of coins[i:] that make left
        if left == 0:
            return 1
        if i == len(coins):
            return 0
        count = ways(i + 1, left)         # no more of coin i
        if coins[i] <= left:
            count += ways(i, left - coins[i])   # one more coin i: stay on i
        return count

    return ways(0, amount)

