int ways(int[] coins, int i, int left) {         // combinations of coins[i..] that make left
    if (left == 0) return 1;
    if (i == coins.length) return 0;
    if (memo[i][left] != null) return memo[i][left];
    int count = ways(coins, i + 1, left);        // no more of coin i
    if (coins[i] <= left) count += ways(coins, i, left - coins[i]);   // one more coin i: stay on i
    memo[i][left] = count;
    return count;
}

vector<vector<unsigned>> memo;                   // unsigned: big counts wrap safely
vector<vector<bool>> solved;

unsigned ways(vector<int>& coins, int i, int left) {   // combinations of coins[i..] that make left
    if (left == 0) return 1;
    if (i == (int)coins.size()) return 0;
    if (solved[i][left]) return memo[i][left];
    unsigned count = ways(coins, i + 1, left);   // no more of coin i
    if (coins[i] <= left) count += ways(coins, i, left - coins[i]);   // one more coin i: stay on i
    solved[i][left] = true;
    return memo[i][left] = count;
}

int change(int amount, vector<int>& coins) {
    memo.assign(coins.size(), vector<unsigned>(amount + 1, 0));
    solved.assign(coins.size(), vector<bool>(amount + 1, false));
    return ways(coins, 0, amount);
}

function change(amount, coins) {
  const k = coins.length;
  // ways[i][a]: combinations that make a using only the first i coin types
  const ways = Array.from({ length: k + 1 }, () => new Array(amount + 1).fill(0));
  for (let i = 0; i <= k; i++) ways[i][0] = 1;   // amount 0: take nothing
  for (let i = 1; i <= k; i++) {
    const c = coins[i - 1];
    for (let a = 1; a <= amount; a++) {
      ways[i][a] = ways[i - 1][a];               // no coin c at all
      if (c <= a) ways[i][a] += ways[i][a - c];  // at least one c: same row, so c can repeat
    }
  }
  return ways[k][amount];
}

